-- Fixed GRT bus + ION snapshot, downloaded 2026-11-05.
-- Source: https://www.grt.ca/about-grt/open-data/
-- Contains information provided by the Regional Municipality of Waterloo under licence.
-- Licence: https://regionofwaterloo-018-ca.govstack.com/government-and-council/transparency-and-accountability/open-data/
-- Bus ZIP SHA-256: e7aed6e06064c7b243ad9ca9b4233cc1abe4d41d69d7c286b45a606f4f658811
-- ION ZIP SHA-256: 9f872bb7bc6ca99029e6426a50e5a2167a96522f13ad97b92a8177b04a84b34c
-- Weekday: 2026-11-05 repeated Mon-Fri. Weekend: 2026-11-07 repeated Sat-Sun.
-- Holidays ignored. Timetables follow only the primary stop list per direction.
-- Apply after backend startup AutoMigrate, inside a transaction (npm run db:seed).

DO $locations$
DECLARE previous_hash TEXT;
BEGIN
    SELECT sha256 INTO previous_hash FROM seed_imports WHERE name = 'grt-locations';
    IF previous_hash = '3265d5e13cf5092087b4e68a18786f9ab14037bcd6c3fc4706e56289cd7a89dc' THEN
        RAISE NOTICE 'GRT locations already loaded; preserving existing data and edits.';
        RETURN;
    ELSIF previous_hash IS NOT NULL THEN
        RAISE EXCEPTION 'A different GRT snapshot is already seeded.';
    END IF;
    LOCK TABLE routes, stops, route_stops, route_patterns, route_pattern_stops,
        route_shapes IN SHARE ROW EXCLUSIVE MODE;
    IF EXISTS (SELECT 1 FROM routes) OR EXISTS (SELECT 1 FROM stops)
        OR EXISTS (SELECT 1 FROM route_patterns) OR EXISTS (SELECT 1 FROM route_shapes) THEN
        RAISE EXCEPTION 'Initial GRT seed requires empty transit location tables; no existing data was replaced.';
    END IF;

