JOIN route_patterns p ON p.source_id = source.pattern_source_id
JOIN stops s ON s.source_id = source.stop_source_id;

INSERT INTO route_stops (route_id, stop_id, stop_sequence)
SELECT p.route_id, ps.stop_id, ps.stop_sequence
FROM route_patterns p JOIN route_pattern_stops ps ON ps.pattern_id = p.id
WHERE p.is_primary;

    IF (SELECT count(*) FROM routes) <> 104 OR (SELECT count(*) FROM stops) <> 2297
        OR (SELECT count(*) FROM route_shapes) <> 183 OR (SELECT count(*) FROM route_patterns) <> 186
        OR (SELECT count(*) FROM route_pattern_stops) <> 4523 OR (SELECT count(*) FROM route_stops) <> 2862 THEN
        RAISE EXCEPTION 'GRT location seed count mismatch';
    END IF;
    INSERT INTO seed_imports (name, sha256) VALUES ('grt-locations', '3265d5e13cf5092087b4e68a18786f9ab14037bcd6c3fc4706e56289cd7a89dc');
END $locations$;

